444|/* realloc printbuffer if necessary to have at least "needed" bytes more */
445|static unsigned char* ensure(printbuffer * const p, size_t needed)
446|{
447|    unsigned char *newbuffer = NULL;
448|    size_t newsize = 0;
449|
450|    if ((p == NULL) || (p->buffer == NULL))
451|    {
452|        return NULL;
453|    }
454|
455|    if ((p->length > 0) && (p->offset >= p->length))
456|    {
457|        /* make sure that offset is valid */
458|        return NULL;
459|    }
460|
461|    if (needed > INT_MAX)
462|    {
463|        /* sizes bigger than INT_MAX are currently not supported */
464|        return NULL;
465|    }
466|
467|    needed += p->offset + 1;
468|    if (needed <= p->length)
469|    {
470|        return p->buffer + p->offset;
471|    }
472|
473|    if (p->noalloc) {
474|        return NULL;
475|    }
476|
477|    /* calculate new buffer size */
478|    if (needed > (INT_MAX / 2))
479|    {
480|        /* overflow of int, use INT_MAX if possible */
481|        if (needed <= INT_MAX)
482|        {
483|            newsize = INT_MAX;
484|        }
485|        else
486|        {
487|            return NULL;
488|        }
489|    }
490|    else
491|    {
492|        newsize = needed * 2;
493|    }
494|
495|    if (p->hooks.reallocate != NULL)
496|    {
497|        /* reallocate with realloc if available */
498|        newbuffer = (unsigned char*)p->hooks.reallocate(p->buffer, newsize);
499|        if (newbuffer == NULL)
500|        {
501|            p->hooks.deallocate(p->buffer);
502|            p->length = 0;
503|            p->buffer = NULL;
504|
505|            return NULL;
506|        }
507|    }
508|    else
509|    {
510|        /* otherwise reallocate manually */
511|        newbuffer = (unsigned char*)p->hooks.allocate(newsize);
512|        if (!newbuffer)
513|        {
514|            p->hooks.deallocate(p->buffer);
515|            p->length = 0;
516|            p->buffer = NULL;
517|
518|            return NULL;
519|        }
520|
521|        memcpy(newbuffer, p->buffer, p->offset + 1);
522|        p->hooks.deallocate(p->buffer);
523|    }
524|    p->length = newsize;
525|    p->buffer = newbuffer;
526|
527|    return newbuffer + p->offset;
