543|/* securely comparison of floating-point variables */
544|static cJSON_bool compare_double(double a, double b)
545|{
546|    double maxVal = fabs(a) > fabs(b) ? fabs(a) : fabs(b);
547|    return (fabs(a - b) <= maxVal * DBL_EPSILON);
