550|/* Render the number nicely from the given item into a string. */
551|static cJSON_bool print_number(const cJSON * const item, printbuffer * const output_buffer)
552|{
553|    unsigned char *output_pointer = NULL;
554|    double d = item->valuedouble;
555|    int length = 0;
556|    size_t i = 0;
557|    unsigned char number_buffer[26] = {0}; /* temporary buffer to print the number into */
558|    unsigned char decimal_point = get_decimal_point();
559|    double test = 0.0;
560|
561|    if (output_buffer == NULL)
562|    {
563|        return false;
564|    }
565|
566|    /* This checks for NaN and Infinity */
567|    if (isnan(d) || isinf(d))
568|    {
569|        length = sprintf((char*)number_buffer, "null");
570|    }
571|	else if(d == (double)item->valueint)
572|	{
573|		length = sprintf((char*)number_buffer, "%d", item->valueint);
574|	}
575|    else
576|    {
577|        /* Try 15 decimal places of precision to avoid nonsignificant nonzero digits */
578|        length = sprintf((char*)number_buffer, "%1.15g", d);
579|
580|        /* Check whether the original double can be recovered */
581|        if ((sscanf((char*)number_buffer, "%lg", &test) != 1) || !compare_double((double)test, d))
582|        {
583|            /* If not, print with 17 decimal places of precision */
584|            length = sprintf((char*)number_buffer, "%1.17g", d);
585|        }
586|    }
587|
588|    /* sprintf failed or buffer overrun occurred */
589|    if ((length < 0) || (length > (int)(sizeof(number_buffer) - 1)))
590|    {
591|        return false;
592|    }
593|
594|    /* reserve appropriate space in the output */
595|    output_pointer = ensure(output_buffer, (size_t)length + sizeof(""));
