630|        {
631|            h += (unsigned int) input[i] - '0';
632|        }
633|        else if ((input[i] >= 'A') && (input[i] <= 'F'))
634|        {
635|            h += (unsigned int) 10 + input[i] - 'A';
636|        }
637|        else if ((input[i] >= 'a') && (input[i] <= 'f'))
638|        {
