1317|/* Parser core - when encountering text, process appropriately. */
1318|static cJSON_bool parse_value(cJSON * const item, parse_buffer * const input_buffer)
1319|{
1320|    if ((input_buffer == NULL) || (input_buffer->content == NULL))
1321|    {
1322|        return false; /* no input */
1323|    }
1324|
1325|    /* parse the different types of values */
1326|    /* null */
1327|    if (can_read(input_buffer, 4) && (strncmp((const char*)buffer_at_offset(input_buffer), "null", 4) == 0))
1328|    {
1329|        item->type = cJSON_NULL;
1330|        input_buffer->offset += 4;
1331|        return true;
1332|    }
1333|    /* false */
1334|    if (can_read(input_buffer, 5) && (strncmp((const char*)buffer_at_offset(input_buffer), "false", 5) == 0))
1335|    {
1336|        item->type = cJSON_False;
1337|        input_buffer->offset += 5;
1338|        return true;
1339|    }
1340|    /* true */
1341|    if (can_read(input_buffer, 4) && (strncmp((const char*)buffer_at_offset(input_buffer), "true", 4) == 0))
1342|    {
1343|        item->type = cJSON_True;
1344|        item->valueint = 1;
1345|        input_buffer->offset += 4;
1346|        return true;
1347|    }
1348|    /* string */
1349|    if (can_access_at_index(input_buffer, 0) && (buffer_at_offset(input_buffer)[0] == '\"'))
1350|    {
1351|        return parse_string(item, input_buffer);
1352|    }
1353|    /* number */
1354|    if (can_access_at_index(input_buffer, 0) && ((buffer_at_offset(input_buffer)[0] == '-') || ((buffer_at_offset(input_buffer)[0] >= '0') && (buffer_at_offset(input_buffer)[0] <= '9'))))
1355|    {
1356|        return parse_number(item, input_buffer);
1357|    }
1358|    /* array */
1359|    if (can_access_at_index(input_buffer, 0) && (buffer_at_offset(input_buffer)[0] == '['))
1360|    {
1361|        return parse_array(item, input_buffer);
1362|    }
1363|    /* object */
1364|    if (can_access_at_index(input_buffer, 0) && (buffer_at_offset(input_buffer)[0] == '{'))
1365|    {
1366|        return parse_object(item, input_buffer);
1367|    }
1368|
1369|    return false;
