1372|/* Render a value to text. */
1373|static cJSON_bool print_value(const cJSON * const item, printbuffer * const output_buffer)
1374|{
1375|    unsigned char *output = NULL;
1376|
1377|    if ((item == NULL) || (output_buffer == NULL))
1378|    {
1379|        return false;
1380|    }
1381|
1382|    switch ((item->type) & 0xFF)
1383|    {
1384|        case cJSON_NULL:
1385|            output = ensure(output_buffer, 5);
1386|            if (output == NULL)
1387|            {
1388|                return false;
1389|            }
1390|            strcpy((char*)output, "null");
1391|            return true;
1392|
1393|        case cJSON_False:
1394|            output = ensure(output_buffer, 6);
1395|            if (output == NULL)
1396|            {
1397|                return false;
1398|            }
1399|            strcpy((char*)output, "false");
1400|            return true;
1401|
1402|        case cJSON_True:
1403|            output = ensure(output_buffer, 5);
1404|            if (output == NULL)
1405|            {
1406|                return false;
1407|            }
1408|            strcpy((char*)output, "true");
1409|            return true;
1410|
1411|        case cJSON_Number:
1412|            return print_number(item, output_buffer);
1413|
1414|        case cJSON_Raw:
1415|        {
1416|            size_t raw_length = 0;
1417|            if (item->valuestring == NULL)
1418|            {
1419|                return false;
1420|            }
1421|
1422|            raw_length = strlen(item->valuestring) + sizeof("");
1423|            output = ensure(output_buffer, raw_length);
1424|            if (output == NULL)
1425|            {
1426|                return false;
1427|            }
1428|            memcpy(output, item->valuestring, raw_length);
1429|            return true;
1430|        }
1431|
1432|        case cJSON_String:
1433|            return print_string(item, output_buffer);
1434|
1435|        case cJSON_Array:
1436|            return print_array(item, output_buffer);
1437|
1438|        case cJSON_Object:
1439|            return print_object(item, output_buffer);
1440|
1441|        default:
1442|            return false;
1443|    }
