1446|/* Build an array from input text. */
1447|static cJSON_bool parse_array(cJSON * const item, parse_buffer * const input_buffer)
1448|{
1449|    cJSON *head = NULL; /* head of the linked list */
1450|    cJSON *current_item = NULL;
1451|
1452|    if (input_buffer->depth >= CJSON_NESTING_LIMIT)
1453|    {
1454|        return false; /* to deeply nested */
1455|    }
1456|    input_buffer->depth++;
1457|
1458|    if (buffer_at_offset(input_buffer)[0] != '[')
1459|    {
1460|        /* not an array */
1461|        goto fail;
1462|    }
1463|
1464|    input_buffer->offset++;
1465|    buffer_skip_whitespace(input_buffer);
1466|    if (can_access_at_index(input_buffer, 0) && (buffer_at_offset(input_buffer)[0] == ']'))
1467|    {
1468|        /* empty array */
1469|        goto success;
1470|    }
1471|
1472|    /* check if we skipped to the end of the buffer */
1473|    if (cannot_access_at_index(input_buffer, 0))
1474|    {
1475|        input_buffer->offset--;
1476|        goto fail;
1477|    }
1478|
1479|    /* step back to character in front of the first element */
1480|    input_buffer->offset--;
1481|    /* loop through the comma separated array elements */
1482|    do
1483|    {
1484|        /* allocate next item */
1485|        cJSON *new_item = cJSON_New_Item(&(input_buffer->hooks));
1486|        if (new_item == NULL)
1487|        {
1488|            goto fail; /* allocation failure */
1489|        }
1490|
1491|        /* attach next item to list */
1492|        if (head == NULL)
1493|        {
1494|            /* start the linked list */
1495|            current_item = head = new_item;
1496|        }
1497|        else
1498|        {
1499|            /* add to the end and advance */
1500|            current_item->next = new_item;
1501|            new_item->prev = current_item;
1502|            current_item = new_item;
1503|        }
1504|
1505|        /* parse next value */
1506|        input_buffer->offset++;
1507|        buffer_skip_whitespace(input_buffer);
1508|        if (!parse_value(current_item, input_buffer))
1509|        {
1510|            goto fail; /* failed to parse value */
1511|        }
1512|        buffer_skip_whitespace(input_buffer);
1513|    }
1514|    while (can_access_at_index(input_buffer, 0) && (buffer_at_offset(input_buffer)[0] == ','));
1515|
1516|    if (cannot_access_at_index(input_buffer, 0) || buffer_at_offset(input_buffer)[0] != ']')
1517|    {
1518|        goto fail; /* expected end of array */
1519|    }
1520|
1521|success:
1522|    input_buffer->depth--;
1523|
1524|    if (head != NULL) {
1525|        head->prev = current_item;
1526|    }
1527|
1528|    item->type = cJSON_Array;
1529|    item->child = head;
1530|
1531|    input_buffer->offset++;
1532|
1533|    return true;
1534|
1535|fail:
1536|    if (head != NULL)
1537|    {
1538|        cJSON_Delete(head);
1539|    }
1540|
1541|    return false;
1542|}
