1545|static cJSON_bool print_array(const cJSON * const item, printbuffer * const output_buffer)
1546|{
1547|    unsigned char *output_pointer = NULL;
1548|    size_t length = 0;
1549|    cJSON *current_element = item->child;
1550|
1551|    if (output_buffer == NULL)
1552|    {
1553|        return false;
1554|    }
1555|
1556|    /* Compose the output array. */
