2198|CJSON_PUBLIC(cJSON *) cJSON_DetachItemViaPointer(cJSON *parent, cJSON * const item)
2199|{
2200|    if ((parent == NULL) || (item == NULL))
2201|    {
2202|        return NULL;
2203|    }
2204|
2205|    if (item != parent->child)
2206|    {
2207|        /* not the first element */
2208|        item->prev->next = item->next;
2209|    }
2210|    if (item->next != NULL)
2211|    {
2212|        /* not the last element */
2213|        item->next->prev = item->prev;
2214|    }
2215|
2216|    if (item == parent->child)
2217|    {
2218|        /* first element */
2219|        parent->child = item->next;
2220|    }
2221|    else if (item->next == NULL)
2222|    {
2223|        /* last element */
2224|        parent->child->prev = item->prev;
2225|    }
2226|
2227|    /* make sure the detached item doesn't point anywhere anymore */
2228|    item->prev = NULL;
2229|    item->next = NULL;
2230|
2231|    return item;
