2308|CJSON_PUBLIC(cJSON_bool) cJSON_ReplaceItemViaPointer(cJSON * const parent, cJSON * const item, cJSON * replacement)
2309|{
2310|    if ((parent == NULL) || (parent->child == NULL) || (replacement == NULL) || (item == NULL))
2311|    {
