2313|    }
2314|
2315|    if (replacement == item)
2316|    {
2317|        return true;
2318|    }
2319|
2320|    replacement->next = item->next;
2321|    replacement->prev = item->prev;
2322|
2323|    if (replacement->next != NULL)
2324|    {
2325|        replacement->next->prev = replacement;
2326|    }
2327|    if (parent->child == item)
