2721|/* Duplication */
2722|CJSON_PUBLIC(cJSON *) cJSON_Duplicate(const cJSON *item, cJSON_bool recurse)
2723|{
2724|    cJSON *newitem = NULL;
2725|    cJSON *child = NULL;
2726|    cJSON *next = NULL;
2727|    cJSON *newchild = NULL;
2728|
2729|    /* Bail on bad ptr */
2730|    if (!item)
2731|    {
2732|        goto fail;
2733|    }
2734|    /* Create new item */
2735|    newitem = cJSON_New_Item(&global_hooks);
2736|    if (!newitem)
2737|    {
2738|        goto fail;
2739|    }
2740|    /* Copy over all vars */
2741|    newitem->type = item->type & (~cJSON_IsReference);
2742|    newitem->valueint = item->valueint;
2743|    newitem->valuedouble = item->valuedouble;
2744|    if (item->valuestring)
2745|    {
2746|        newitem->valuestring = (char*)cJSON_strdup((unsigned char*)item->valuestring, &global_hooks);
2747|        if (!newitem->valuestring)
2748|        {
2749|            goto fail;
2750|        }
2751|    }
2752|    if (item->string)
2753|    {
2754|        newitem->string = (item->type&cJSON_StringIsConst) ? item->string : (char*)cJSON_strdup((unsigned char*)item->string, &global_hooks);
2755|        if (!newitem->string)
2756|        {
2757|            goto fail;
2758|        }
2759|    }
2760|    /* If non-recursive, then we're done! */
2761|    if (!recurse)
2762|    {
2763|        return newitem;
2764|    }
2765|    /* Walk the ->next chain for the child. */
2766|    child = item->child;
2767|    while (child != NULL)
2768|    {
2769|        newchild = cJSON_Duplicate(child, true); /* Duplicate (with recurse) each item in the ->next chain */
2770|        if (!newchild)
2771|        {
2772|            goto fail;
2773|        }
2774|        if (next != NULL)
2775|        {
2776|            /* If newitem->child already set, then crosswire ->prev and ->next and move on */
2777|            next->next = newchild;
2778|            newchild->prev = next;
2779|            next = newchild;
2780|        }
2781|        else
2782|        {
2783|            /* Set newitem->child and move to it */
2784|            newitem->child = newchild;
2785|            next = newchild;
2786|        }
2787|        child = child->next;
2788|    }
2789|    if (newitem && newitem->child)
2790|    {
2791|        newitem->child->prev = newchild;
2792|    }
2793|
2794|    return newitem;
