2805|static void skip_oneline_comment(char **input)
2806|{
2807|    *input += static_strlen("//");
2808|
2809|    for (; (*input)[0] != '\0'; ++(*input))
2810|    {
2811|        if ((*input)[0] == '\n') {
2812|            *input += static_strlen("\n");
2813|            return;
2814|        }
2815|    }
2816|}
