2818|static void skip_multiline_comment(char **input)
2819|{
2820|    *input += static_strlen("/*");
2821|
2822|    for (; (*input)[0] != '\0'; ++(*input))
2823|    {
2824|        if (((*input)[0] == '*') && ((*input)[1] == '/'))
2825|        {
2826|            *input += static_strlen("*/");
2827|            return;
2828|        }
2829|    }
2830|}
