2832|static void minify_string(char **input, char **output) {
2833|    (*output)[0] = (*input)[0];
2834|    *input += static_strlen("\"");
2835|    *output += static_strlen("\"");
2836|
2837|
2838|    for (; (*input)[0] != '\0'; (void)++(*input), ++(*output)) {
2839|        (*output)[0] = (*input)[0];
2840|
2841|        if ((*input)[0] == '\"') {
2842|            (*output)[0] = '\"';
2843|            *input += static_strlen("\"");
2844|            *output += static_strlen("\"");
2845|            return;
2846|        } else if (((*input)[0] == '\\') && ((*input)[1] == '\"')) {
2847|            (*output)[1] = (*input)[1];
2848|            *input += static_strlen("\"");
2849|            *output += static_strlen("\"");
2850|        }
2851|    }
