2854|CJSON_PUBLIC(void) cJSON_Minify(char *json)
2855|{
2856|    char *into = json;
2857|
2858|    if (json == NULL)
2859|    {
2860|        return;
2861|    }
2862|
2863|    while (json[0] != '\0')
2864|    {
2865|        switch (json[0])
2866|        {
2867|            case ' ':
2868|            case '\t':
2869|            case '\r':
2870|            case '\n':
2871|                json++;
2872|                break;
2873|
2874|            case '/':
2875|                if (json[1] == '/')
2876|                {
2877|                    skip_oneline_comment(&json);
2878|                }
2879|                else if (json[1] == '*')
2880|                {
2881|                    skip_multiline_comment(&json);
2882|                } else {
2883|                    json++;
2884|                }
2885|                break;
2886|
2887|            case '\"':
2888|                minify_string(&json, (char**)&into);
2889|                break;
2890|
2891|            default:
2892|                into[0] = json[0];
2893|                json++;
2894|                into++;
2895|        }
2896|    }
2897|
2898|    /* and null-terminate. */
2899|    *into = '\0';
