3002|CJSON_PUBLIC(cJSON_bool) cJSON_Compare(const cJSON * const a, const cJSON * const b, const cJSON_bool case_sensitive)
3003|{
3004|    if ((a == NULL) || (b == NULL) || ((a->type & 0xFF) != (b->type & 0xFF)))
3005|    {
3006|        return false;
3007|    }
3008|
3009|    /* check if type is valid */
3010|    switch (a->type & 0xFF)
3011|    {
3012|        case cJSON_False:
3013|        case cJSON_True:
3014|        case cJSON_NULL:
3015|        case cJSON_Number:
3016|        case cJSON_String:
3017|        case cJSON_Raw:
3018|        case cJSON_Array:
3019|        case cJSON_Object:
3020|            break;
3021|
3022|        default:
3023|            return false;
3024|    }
3025|
3026|    /* identical objects are equal */
3027|    if (a == b)
3028|    {
3029|        return true;
3030|    }
3031|
3032|    switch (a->type & 0xFF)
3033|    {
3034|        /* in these cases and equal type is enough */
3035|        case cJSON_False:
3036|        case cJSON_True:
3037|        case cJSON_NULL:
3038|            return true;
3039|
3040|        case cJSON_Number:
3041|            if (compare_double(a->valuedouble, b->valuedouble))
3042|            {
3043|                return true;
3044|            }
3045|            return false;
3046|
3047|        case cJSON_String:
3048|        case cJSON_Raw:
3049|            if ((a->valuestring == NULL) || (b->valuestring == NULL))
3050|            {
3051|                return false;
3052|            }
3053|            if (strcmp(a->valuestring, b->valuestring) == 0)
3054|            {
3055|                return true;
3056|            }
3057|
3058|            return false;
3059|
3060|        case cJSON_Array:
3061|        {
3062|            cJSON *a_element = a->child;
3063|            cJSON *b_element = b->child;
3064|
3065|            for (; (a_element != NULL) && (b_element != NULL);)
3066|            {
3067|                if (!cJSON_Compare(a_element, b_element, case_sensitive))
3068|                {
3069|                    return false;
3070|                }
3071|
3072|                a_element = a_element->next;
3073|                b_element = b_element->next;
3074|            }
3075|
3076|            /* one of the arrays is longer than the other */
3077|            if (a_element != b_element) {
3078|                return false;
3079|            }
3080|
3081|            return true;
3082|        }
3083|
3084|        case cJSON_Object:
3085|        {
3086|            cJSON *a_element = NULL;
3087|            cJSON *b_element = NULL;
3088|            cJSON_ArrayForEach(a_element, a)
3089|            {
3090|                /* TODO This has O(n^2) runtime, which is horrible! */
3091|                b_element = get_object_item(b, a_element->string, case_sensitive);
3092|                if (b_element == NULL)
3093|                {
3094|                    return false;
3095|                }
3096|
3097|                if (!cJSON_Compare(a_element, b_element, case_sensitive))
3098|                {
3099|                    return false;
3100|                }
3101|            }
3102|
3103|            /* doing this twice, once on a and b to prevent true comparison if a subset of b
3104|             * TODO: Do this the proper way, this is just a fix for now */
3105|            cJSON_ArrayForEach(b_element, b)
3106|            {
3107|                a_element = get_object_item(a, b_element->string, case_sensitive);
3108|                if (a_element == NULL)
3109|                {
3110|                    return false;
3111|                }
3112|
3113|                if (!cJSON_Compare(b_element, a_element, case_sensitive))
3114|                {
3115|                    return false;
3116|                }
3117|            }
3118|
3119|            return true;
3120|        }
3121|
3122|        default:
3123|            return false;
3124|    }
3125|}
