133|static int case_insensitive_strcmp(const unsigned char *string1, const unsigned char *string2)
134|{
135|    if ((string1 == NULL) || (string2 == NULL))
136|    {
137|        return 1;
138|    }
139|
140|    if (string1 == string2)
141|    {
142|        return 0;
143|    }
