1357|    {
1358|        return parse_string(item, input_buffer);
1359|    }
1360|    /* number */
1361|    if (can_access_at_index(input_buffer, 0) && ((buffer_at_offset(input_buffer)[0] == '-') || ((buffer_at_offset(input_buffer)[0] >= '0') && (buffer_at_offset(input_buffer)[0] <= '9'))))
