2812|static void skip_oneline_comment(char **input)
2813|{
2814|    *input += static_strlen("//");
2815|
2816|    for (; (*input)[0] != '\0'; ++(*input))
2817|    {
2818|        if ((*input)[0] == '\n') {
2819|            *input += static_strlen("\n");
2820|            return;
2821|        }
2822|    }
2823|}
