2825|static void skip_multiline_comment(char **input)
2826|{
2827|    *input += static_strlen("/*");
2828|
2829|    for (; (*input)[0] != '\0'; ++(*input))
2830|    {
2831|        if (((*input)[0] == '*') && ((*input)[1] == '/'))
2832|        {
2833|            *input += static_strlen("*/");
2834|            return;
2835|        }
2836|    }
2837|}
