2861|CJSON_PUBLIC(void) cJSON_Minify(char *json)
2862|{
2863|    char *into = json;
2864|
2865|    if (json == NULL)
2866|    {
2867|        return;
2868|    }
2869|
2870|    while (json[0] != '\0')
2871|    {
2872|        switch (json[0])
2873|        {
2874|            case ' ':
2875|            case '\t':
2876|            case '\r':
2877|            case '\n':
2878|                json++;
2879|                break;
2880|
2881|            case '/':
2882|                if (json[1] == '/')
2883|                {
2884|                    skip_oneline_comment(&json);
2885|                }
2886|                else if (json[1] == '*')
2887|                {
2888|                    skip_multiline_comment(&json);
2889|                } else {
2890|                    json++;
2891|                }
2892|                break;
2893|
2894|            case '\"':
2895|                minify_string(&json, (char**)&into);
2896|                break;
2897|
2898|            default:
2899|                into[0] = json[0];
2900|                json++;
2901|                into++;
2902|        }
2903|    }
2904|
2905|    /* and null-terminate. */
2906|    *into = '\0';
